insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 1, 'Least squares is fitted to the 180 training rows of the teaching split, with DT as the target and GR, RHOB and NPHI as the features. What does the course call the model that comes back?', '["The 180 training rows kept beside the fit, so that a new row is predicted from the training row nearest to it.", "Its training R-squared of 0.683457, the one number that describes how the fitted plane sits on the rows.", "The intercept and three coefficients: a rule that turns any row''s three logs into a predicted DT.", "The 90 predicted DT values for the three held-out wells, written out as a new log."]'::jsonb, 2, 'The four numbers are the whole model. To predict a row, multiply each log by its coefficient, add the three products and add the intercept. Nothing else from the 180 rows travels with the rule, so no training row is ever looked up. The training R-squared is a score of the fit on the rows that chose it, and the 90 predicted values are what the rule produces once it is applied; neither is the rule itself.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 2, 'In the Ekene sonic model, which column is the target y, and which columns are the features X?', '["DT is the target; GR, RHOB and NPHI are the features the fit reads.", "GR is the target, since the gamma ray is the log every well carries; DT, RHOB and NPHI are the features.", "PAY is the target, as the label every row carries; GR, RHOB, NPHI and DT are the features it is fitted on.", "Every column is both at once, because least squares predicts each log from all of the others in one fit."]'::jsonb, 0, 'The target is the one column the model learns to predict, here the compressional sonic DT in us/ft, chosen because EKENE-6 was logged without one. The features are logs every well carries. PAY is a label from a stated rule on PHIC and RT, and this tier builds no model of it. Least squares fits one target at a time.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 3, 'A script calls one of the engine''s functions. Which description covers every reply it can get back?', '["A result object in every case, with a list inside `basis` that fills up whenever an input looked doubtful.", "Either a result or an error, where the error also carries the engine''s best estimate from the inputs it could use.", "One result object whose missing entries have been filled with the column mean and listed in a `filled` block.", "Either a result object carrying a `basis` block that names its convention, or an object carrying `error` and `field`."]'::jsonb, 3, 'Every function returns one of two shapes: a result with its `basis` block, or an object with `error` and `field`, where the field names the refused input and the message starts with that name. A refusal carries no number of its own, so it holds no estimate. The engine never fills a missing value, and an input it cannot use is refused by name, so a result that merely notes a doubtful input is a shape it does not return.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 4, 'One GR value in a training well is null when `ols` is called. What does the engine do with it?', '["It fills the entry with the training mean of GR and fits, so the call still returns four coefficients.", "It refuses the call and names the entry, and leaves the choice to fill the value or drop the row to the caller.", "It drops that row without saying so, fits all the other rows and reports the smaller row count in its basis block.", "Zero is put in its place, the value a missing reading holds in most log files, and the fit goes ahead."]'::jsonb, 1, 'The engine does not fill a missing value. A null, undefined or non-finite entry in X or y is refused by name, and filling or dropping it is the caller''s decision, made before the fit. A filled value is a guess that would be scored as a measurement, and silently skipping a row would give a fit on a row count nobody chose. Treating a null as zero is a fill like any other.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 5, 'Which kinds of model does this engine fit?', '["Least squares and decision trees, choosing between the two for you by the lower training RMSE.", "Linear models only, least squares among them; it builds no tree, network, neighbour rule or cluster.", "Any model the caller names, neural networks included, provided the features are scaled first.", "Only least squares, with a clustering step that groups similar wells together before the fit."]'::jsonb, 1, 'The engine fits linear models only, and least squares is the one this tier uses. It builds no tree, no network, no neighbour rule and no cluster, and it does not choose the model or the features for you: a course or an app does that and prints the scores it compared. Clustering belongs to the electrofacies course.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 6, 'The Ekene field has 300 rows, yet every sonic model in this tier works on 270 of them. Why?', '["The engine judged 30 rows of the sonic to be outliers and dropped them before any fit was made.", "Hot shale in EKENE-6 raised its gamma ray, and the scaler refused its 30 rows as out of range.", "Each split holds back the first 30 rows as a fixed test well before the training rows are chosen.", "EKENE-6 was logged without a sonic, so all 30 of its DT samples are null and 9 wells carry a DT."]'::jsonb, 3, 'EKENE-6 has no sonic log, so every one of its DT samples is null: 270 rows in 9 wells carry a DT. The engine flags no outliers (that belongs to the data quality course), and min-max scaling maps rows outside the training range above 1 without refusing them. The test wells of a split change with the seed, so no fixed 30 rows are held back.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 7, 'What is the PAY column in the Ekene table?', '["The output of a stated rule: 1 where PHIC is at least 0.16 and RT is at least 10 ohm.m, and 0 otherwise.", "A pay flag picked by a petrophysicist from core photographs, which the course treats as the ground truth.", "A label the engine assigns from the gamma ray, marking every sample below a shale cutoff as pay.", "Where the sonic model''s predicted DT exceeds the measured DT on a row, PAY is set to 1."]'::jsonb, 0, 'PAY is 1 when PHIC is at least 0.16 and RT is at least 10 ohm.m, and 0 otherwise; 94 of the 300 samples are pay. A label is the output of a stated rule, and this course always states it. The engine assigns no labels of its own, and the sonic model predicts DT and nothing else.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 8, 'Easting, northing, KB and mud weight each hold one value down a whole well. Why does the course ask you to keep that in mind before rows are split?', '["They are null on EKENE-6, so passing them to a fit removes one more well from every model that uses them.", "Down each well they change with depth, so they carry the sonic trend and swamp the three logs in the fit.", "A model handed them can learn which well a row came from, which matters once rows of one well can sit on both sides.", "Every fit refuses all four of them, since a constant column can never be scaled or fitted by the engine."]'::jsonb, 2, 'Each attribute is constant down its well, so it can identify the well a row came from. That matters as soon as rows of one well can land on both sides of a split. The attributes are stated for every well, EKENE-6 included, and they do not change with depth. A scaler fitted on the rows of one well refuses a constant attribute; across the nine sonic wells the same column varies and is fitted.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 9, 'CALI sits in the Ekene table, present on every row. What does the course say about it as a feature for the sonic?', '["It tracks washouts that slow the sonic, which makes it the strongest feature after the neutron porosity.", "`ols` refuses it as a column the engine judges to carry too little information about the target.", "With PHIC it is an input of the pay rule, which is why it is kept.", "It was drawn independently of every other channel, so by design it carries no sonic signal."]'::jsonb, 3, 'The Ekene field drew CALI with no link to any other channel, so it carries no sonic signal by design: a column can be present, clean and useless. The engine never judges whether a column is informative; the only CALI refusal it tables is for a column that is zero in every row. The pay rule reads PHIC and RT.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 10, 'What does the engine''s `predict` need in order to return predicted DT values for a set of rows?', '["The fitted model and those rows'' features; no measured DT is needed at all.", "The fitted model, the rows'' features and their measured DT, so each prediction arrives paired with a residual.", "All the training rows as well, since the rule is fitted again each time a new row is to be predicted.", "A seed, because every prediction is a draw from a distribution placed around the fitted plane."]'::jsonb, 0, '`predict` takes a model and X. A prediction is the fitted rule applied to a row''s features, and it is useful exactly where the target may never have been measured. The coefficients are the whole model, so nothing is refitted. The engine gives no prediction intervals, and its only random draws are seeded shuffles.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 11, '`fitStandardScaler` is handed all 300 rows with GR and DT as its two features and refuses with the field `X[150][1]`. What does that field point at?', '["The 150th row counted from 1, which is a row of EKENE-5, in the first feature column, which is GR.", "A count: 150 missing values were found in column 1 before the scaler gave up.", "Row 150 counted from 0, the first EKENE-6 sample, in column 1, which is DT, the second feature.", "Row 150 among the sonic rows only, since the scaler skips wells with no sonic."]'::jsonb, 2, 'The engine counts rows from 0, and the first EKENE-6 sample is dataset row 150. Column 1 is the second feature column, DT, which is null on every EKENE-6 row. A field names a position and holds no count, and the scaler skips nothing: it stops at the first null it meets and names it.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 12, '`ols` is passed the forty rows from 130 to 169, the last twenty of EKENE-5 and the first twenty of EKENE-6, with DT as the target. Why is the refused field `y[20]`?', '["Counting from 1, y[20] is the twentieth row passed, which is the last EKENE-5 sample in the forty.", "The index counts the rows passed from 0, and the twenty-first row passed is the first EKENE-6 sample.", "Twenty of the forty targets are null, and the field reports how many nulls the engine found.", "The engine fitted the first twenty rows, skipped the nulls after them and then reported where it stopped."]'::jsonb, 1, 'The index counts the rows passed, from 0, so `y[20]` is the twenty-first row passed: dataset row 150, the first EKENE-6 sample. The engine stops at the first null it meets and returns no fit at all, so nothing is skipped. The field is a position; the message, in the engine''s own words, is "y[20] must be a finite number".'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 13, '`ols` is handed three rows for three logs and an intercept. Which field does the refusal name, and why that one?', '["`X`, because the whole design is too small and no single entry is to blame.", "`y`, because the target has too few values to estimate a residual standard error from.", "`X[2]`, the last row passed, because that is the row where the engine ran out of rows to use.", "`intercept`, because dropping it would leave three coefficients and let the same three rows fit."]'::jsonb, 0, 'Three logs and an intercept are four coefficients, and least squares needs more rows than coefficients. The engine names `X`, the whole design, since no one entry is at fault. Dropping the intercept would leave three coefficients on three rows, still no residual degree of freedom, so the call would still be refused.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 14, 'The refusal for too few rows reads, in the engine''s own words: "X must have more rows than coefficients (3 rows for 4 coefficients, the intercept included): the residual degrees of freedom n - p must be at least 1". What are the 3 and the 4 in it?', '["A partial result: the engine fitted three of the four coefficients and reports how far it got.", "Codes into the engine''s list of refusals, where 3 and 4 together identify which message this is.", "Residual degrees of freedom the fit reached, which the caller can later read back as a numeric field.", "Part of the message, which states its own arithmetic; the refusal returns no number of its own."]'::jsonb, 3, 'A refusal is an object with `error` and `field` and carries no number of its own: any figure in it is part of the message. Here the message counts the rows passed and the coefficients asked for, the intercept included. The engine fits nothing on a refused call, and the field is a name with no code behind it.'),
  ('mlcore', 'beginner', 'module', 'm01-what-a-model-is', 15, 'How does this course use the words "machine learning"?', '["For any automated judgement a program makes about well data, whether fitted or hand-written.", "About models that pick their own features and settings, which this engine does for its caller.", "For a fitted statistical model, always named by its method, such as least squares.", "Only of the scaling step, since that is the one part of the workflow that learns from the data."]'::jsonb, 2, 'The course legislates the word: machine learning here means a fitted statistical model named by its method, and least squares is this tier''s. The wider meaning, any automated judgement, is the one the course sets aside. The engine chooses no features and no model for its caller. A scaler is itself fitted on the training rows, but it is one fitted step among others and is not what the phrase names.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 1, '`randomRowSplit` runs on the 270 sonic rows at test fraction 0.3 and seed 5. How many of the nine sonic wells end up with rows on both sides of the split?', '["None of them, since a split is built so that no well can ever land on both of its sides.", "All 9: every well that gives random-row test rows also trains the model.", "Three, the same three wells that the whole-well split holds out at this seed and fraction.", "Six, the wells that the whole-well split trains on, since only they have rows to spare."]'::jsonb, 1, 'The 81 random-row test rows come from all 9 wells, and each of those wells also trains the model: the engine''s `sharedGroups` lists all nine. None on both sides is the whole-well split''s figure, and three is the number of wells that split holds out.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 2, 'At test fraction 0.3 and seed 5, which wells does `groupSplit` hold out of the nine sonic wells?', '["EKENE-2, EKENE-7 and EKENE-8, 90 rows; the other six wells train the model on 180 rows.", "EKENE-8, EKENE-4, EKENE-5 and EKENE-2, the first four names of the shuffled order at seed 5.", "EKENE-1, EKENE-10 and EKENE-2, the first three names of the sorted list before any shuffle.", "EKENE-4, EKENE-5 and EKENE-8, 90 rows, leaving six wells and 180 rows to train."]'::jsonb, 3, 'At seed 5 the shuffled order begins EKENE-8, EKENE-4, EKENE-5, and the first three are the test wells: 90 rows, with EKENE-1, EKENE-10, EKENE-2, EKENE-3, EKENE-7 and EKENE-9 training on 180. EKENE-2, EKENE-7 and EKENE-8 is the draw at seed 1. The test size is ceil(0.3 x 9) = 3 wells, so a fourth name is not held out, and the sorted list is only the starting point of the shuffle.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 3, 'At the same fraction 0.3, `randomRowSplit` holds out 81 of the 270 sonic rows while `groupSplit` holds out 90. Why do the two counts differ?', '["The row split takes ceil(0.3 x 270) = 81 rows; the well split takes ceil(0.3 x 9) = 3 wells, and every row of each goes with it.", "The well split rounds its test size up to the next ten rows so that every test well can stay whole.", "The row split drops the rows it finds on both sides, which takes 9 rows out of its test set.", "Each split draws its own fraction near 0.3 from the seed, so the two sizes land apart by chance."]'::jsonb, 0, 'Both splits use the same rule, ceil(testFraction x count). The row split counts rows and holds out 81. The well split counts wells, holds out 3 of the 9, and takes all 90 of their rows with them. No rounding to tens is involved, nothing is dropped, and the fraction is stated: the seed decides which rows or wells, never how many.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 4, 'What does the engine''s basis say `randomRowSplit` is for?', '["Scoring a model quickly whenever a field has too few wells for a split by whole wells to work.", "Balancing test rows across the wells, so that each well is tested in proportion to its size.", "Demonstrating leakage only; to score a model it points to a split by whole wells.", "A stand-in for `groupSplit` wherever a seed must repeat."]'::jsonb, 2, 'The engine''s own words are: "leakage demonstration only: rows of one well can fall on both sides (sharedGroups); use groupSplit or groupKFold to score a model". The function exists so you can see what happens when rows of one well sit on both sides. Both splits are seeded and repeatable, and nothing in the basis offers the row split as a scoring tool for a field with few wells.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 5, 'A report says a model scored an RMSE on its "test" rows and names no split. In this course, what does the word promise?', '["Rows set aside at random, one at a time, across every well of the field.", "The rows with the largest residuals, kept back to check the fit where it is weakest.", "Rows the model was not fitted on, held out as whole wells.", "Any check of a model at all, a score on the rows it was fitted on included."]'::jsonb, 2, 'The course legislates the word: a test row is a row the model was not fitted on, and a test set is a whole well held out unless the text names a random-row split. Rows picked at random must be named as a random-row split. Rows chosen by their residuals were chosen after a fit, and a score on the fitting rows is a training score.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 6, 'Why does this course hold out whole wells when it builds a test set?', '["Each well carries its own sonic offset on every row, so a row from a training well shares what the model has already met.", "Wells are the only unit the engine''s splitting functions accept, because a row carries no name.", "A single row is too short for least squares to score, since RMSE needs 30 rows before it is defined.", "Whole wells hold out more rows at the same fraction, and the course wants as large a test set as it can possibly get from nine wells."]'::jsonb, 0, 'Each Ekene well adds its own offset to every DT sample, so the rows of a well sit above or below the others as a block. A row from a training well is barely new. A new well brings its own offset, and holding out whole wells asks that question. `randomRowSplit` takes a row count, RMSE has no 30-row minimum, and the 90 against 81 difference is a matter of rounding a count of wells.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 7, 'A model has no feature that identifies a well. How does a random-row test score compare with a whole-well test score, both split from the same 270 sonic rows?', '["It comes out lower on every draw, since a random-row split always lets the model meet each well''s offset.", "It comes out higher on every draw, since a random-row test set is smaller and so carries larger misses.", "The two come out identical, since both splits hold out the same fraction of the 270 sonic rows.", "It can come out on either side as the draw falls; with no such feature neither direction is assured."]'::jsonb, 3, 'If a feature lets the model recognise a well, it can learn each well''s offset from the training rows and meet it again in the random-row test rows. If nothing identifies a well, there is no such path, and the random-row score can land on either side of a whole-well score. Whichever way its number moves, it is never the honest estimate for a new well. The two splits also hold out different rows, 81 against 90.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 8, 'At fraction 0.3, seed 2 holds out EKENE-1, EKENE-5 and EKENE-9, and seed 5 holds out EKENE-4, EKENE-5 and EKENE-8. What does that say about the seed?', '["Seed 5 is the right draw, since it is the teaching split that this tier measures everything on.", "It fixes which wells are drawn and nothing else; a score on one set is a score on those wells.", "Seed 2 is the fairer draw, as its wells spread further through the sorted names.", "EKENE-5 must be the hardest well to predict, because two different seeds both chose to hold it out."]'::jsonb, 1, 'A seed fixes the draw and nothing else. Each set of test wells is a fair draw and none is the right one; the teaching split is simply the one the course states and quotes. Any other seed holds out another set and gives another score. The shuffle knows nothing of a well''s difficulty, so a well drawn twice says nothing about how hard it is to predict.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 9, 'Why does EKENE-10 sit second in the engine''s sorted list of the nine sonic wells, ahead of EKENE-2?', '["Names sort by UTF-16 code unit, character by character, and the character 1 comes before the character 2.", "The engine reads the number inside each name and sorts by it, after a first pass on name length.", "The list is sorted by top depth, and EKENE-10''s first sample lies shallower than EKENE-2''s.", "Wells are listed in the order they were drilled, as the field''s table of wells records against each of the names."]'::jsonb, 0, 'String names sort by UTF-16 code unit, so EKENE-10 comes before EKENE-2 because 1 comes before 2. The engine does not read the number inside a name. Top depth plays no part, and EKENE-10''s top at 8304 ft is the deepest in the table anyway. No drilling order is recorded.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 10, 'In the seed 5 shuffle of the nine sonic wells, the draw at i = 2 is u = 0.720102. What happens at that step?', '["j = 3, so EKENE-5 swaps with the name at position 3 and moves one place towards the end of the list.", "The draw is thrown away, because a name may not swap with itself, and a fresh u is drawn in its place.", "Shuffling stops at this step, because a repeated position shows that the order has already settled.", "j = floor(u x 3) = 2, so EKENE-5 swaps with itself and the order stays as it was."]'::jsonb, 3, 'Fisher-Yates from the end takes j = floor(u x (i + 1)); at i = 2 that is j = 2, and the course''s table records EKENE-5 swapping with EKENE-5. A self-swap is allowed and changes nothing. No draw is discarded, and the loop runs on down to i = 1, which swaps EKENE-8 with EKENE-4.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 11, 'After the shuffle, which rule does `groupSplit` apply to choose its test wells?', '["The last nTest groups of the shuffled order are the test set, so that the first ones can train.", "The first nTest groups of the shuffled order are the test set, and every row of a group goes with it.", "Groups are drawn one at a time until their rows reach the test fraction of the total row count.", "Test wells are the nTest groups with the fewest rows, which keeps the training set as large as it can possibly be."]'::jsonb, 1, 'The engine''s own words are: "the first nTest groups of the shuffled order are the test set; every row of a group goes with it". At seed 5 the order starts EKENE-8, EKENE-4, EKENE-5, and those three are held out. The count of test groups is fixed first by ceil(testFraction x count); row counts and group sizes play no part in which groups are chosen.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 12, '`groupSplit` is given 25 groups at fraction 0.28. In float, 0.28 x 25 comes out as 7 plus 8.88e-16. How many groups does it hold out?', '["8, since the ceiling of anything even a hair above 7 is 8, and the engine applies it exactly as written.", "6, as the engine rounds the product down, so that the training set never loses a whole group to float noise.", "7, because a product within 1.00e-9 of a whole number is taken as that number before the ceiling.", "Seven groups and part of an eighth, split by rows, so the test share lands on 0.28."]'::jsonb, 2, 'The engine''s basis states the rule: "ceil(testFraction x count), a product within 1e-9 of a whole number taken as that number". 8.88e-16 is well within 1.00e-9, so the product is taken as 7 and 7 groups are held out; a plain ceiling would have held out 8. The engine does not round down, and a group is always held out whole.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 13, 'A call to `groupSplit` passes nTestGroups 1 and testFraction 0.3 together. What comes back?', '["One held-out well, since the number of wells takes precedence over the fraction.", "Three test wells, because the fraction takes precedence and the count is ignored.", "Four wells in the test set: the one named plus the three the fraction asks for.", "A refusal naming `nTestGroups`, whose message is \"nTestGroups and testFraction cannot both be given\"."]'::jsonb, 3, 'Pass one size or the other. Given both, the engine refuses on the field `nTestGroups` in the words quoted, and returns no split. Neither setting takes precedence, and the two are never added together.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 14, '`groupSplit` on the nine sonic wells is asked for fraction 0.95. What does the engine return?', '["A refusal on `testFraction`, because ceil(0.95 x 9) = 9 puts every group in the test set and none is left to train.", "Eight test wells and one training well, since the engine always keeps back one well when it must.", "All nine wells as the test set, with nothing trained and every score in the result left empty.", "The fraction lowered to 0.3 by the engine, with a note in the basis naming the change it made."]'::jsonb, 0, 'The engine''s own words are: "testFraction puts all 9 groups in the test set (ceil(0.95 x 9) = 9): lower it so at least one group trains". It changes no setting on your behalf, it does not return an empty split, and it does not quietly hold out fewer wells than the fraction asks for: it refuses and names the field.'),
  ('mlcore', 'beginner', 'module', 'm02-data-the-model-has-not-seen', 15, 'What does the engine accept as the seed of a split?', '["Any number at all, a negative one included, which the engine maps into its range first.", "A whole number from 0 to 4294967295; a negative seed is refused on the field `seed`.", "Only the seeds 1 to 6, which the course tables for the nine sonic wells.", "A text label such as a well name, turned into a number by sorting."]'::jsonb, 1, 'The engine''s own words are: "seed must be a whole number from 0 to 4294967295", and a negative seed is refused on `seed`. Nothing is mapped into range silently. Seeds 1 to 6 are simply the ones the course prints, and a seed is a number, which the sorting of well names does not produce.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 1, 'How does the engine''s standard scaler map a feature value x, and on which rows are its two numbers fitted?', '["z = (x - centre) / scale, with a fresh centre and scale fitted on whichever set of rows it is applied to.", "It divides x by the scale alone, fitted on all rows passed, and leaves each feature''s centre where it was.", "Each value becomes (x - minimum) / range from the training rows, so every row lands between 0 and 1.", "z = (x - centre) / scale, with the centre and scale fitted on the training rows and applied unchanged to any other rows."]'::jsonb, 3, 'A standard scaler maps each feature to z = (x - centre) / scale, fits both numbers on the training rows only (the rows passed or the rows `trainIndices` lists) and applies them unchanged to any other rows. Refitting on the rows being transformed would let the test wells shape their own scaling. Minimum over range is min-max scaling, and even that does not keep a new row inside 0 to 1.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 2, 'For the teaching split, which GR centre should the scaler use, and why?', '["60.250741, the mean of all 270 sonic rows, because more rows give a steadier centre for every well.", "59.844500, the mean of the 180 training rows, because the three test wells must influence nothing.", "22.375203, the population standard deviation of those training rows, since a centre measures spread.", "The mean of the 90 test rows, since a scaler should centre the rows it transforms."]'::jsonb, 1, 'The centre is the mean of the training rows: 59.844500 gAPI on the 180 rows of the teaching split. 60.250741 is the mean over all 270 sonic rows, which include EKENE-4, EKENE-5 and EKENE-8, the wells the split promised to keep unseen. 22.375203 is the training scale, and a centre fitted on the test rows would let them shape their own transform.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 3, 'On the 180 training rows, GR''s scale reads 22.375203 with the population standard deviation and 22.437616 with the sample standard deviation. What separates the two?', '["The divisor: n against n - 1, which makes the sample scale larger by the factor 1.002789 on 180 rows.", "Rounding: they are one number printed at two precisions, so either may be quoted for the scale.", "The rows: the sample figure is fitted on all 270 sonic rows and the population one on the training rows.", "An outlier rule: the sample standard deviation drops rows beyond three scales before dividing by n."]'::jsonb, 0, 'The population standard deviation divides by n and the sample standard deviation by n - 1; on 180 rows the sample scale is larger by sqrt(180 / 179), which is 1.002789, for every feature. Both figures are fitted on the same 180 training rows (the all-rows population scale is 21.363430), the gap between them is far larger than rounding at six decimals, and neither drops any row.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 4, 'Why does the engine''s standard scaler divide by n unless told otherwise?', '["Dividing by n - 1 is refused on training sets smaller than 180 rows, as the scaler''s basis states.", "It is the divisor the data quality course uses for its own z-score, and the two courses must agree on it everywhere.", "So that its scale matches the one scikit-learn''s StandardScaler computes on the same rows, as its basis states.", "Dividing by n gives the larger scale of the two, so every standardised value sits closer to zero."]'::jsonb, 2, 'The basis reads, in the engine''s words, "population standard deviation (n), as scikit-learn StandardScaler". The option `sd: ''sample''` divides by n - 1 on any number of rows. The data quality course uses the sample standard deviation, n - 1, which is why the course asks every standard deviation to name its divisor. Dividing by n gives the smaller scale, so the z values come out larger.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 5, 'A caller passes `sd: ''unbiased''` to `fitStandardScaler`. What happens?', '["A refusal on `sd`, whose message is \"sd must be ''population'' or ''sample''\".", "The engine reads it as the sample standard deviation, n - 1, the usual meaning of an unbiased estimate.", "Any unknown value falls back to the population standard deviation, with a note in the basis.", "The scaler fits no scale at all and returns the centres only, so that z = x - centre."]'::jsonb, 0, 'The option takes two values, ''population'' and ''sample'', and any other value is refused on the field `sd` with the message quoted. The engine does not guess what a word was meant to say, it does not fall back to a default for a value it cannot read, and it never returns half a scaler.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 6, 'The training scaler turns the first test row, EKENE-4 at 7966 ft, into z = -0.520420, -0.303186 and -0.360332 for GR, RHOB and NPHI. What do the three signs say?', '["The row is refused as out of range, since a fit on training rows cannot return a negative z.", "It sits below its own well''s centres, since each test row is scaled by the mean of its own well.", "Each log is below zero in its raw unit, so the row reads a negative gamma ray, density and porosity.", "All three logs of that row sit a little below their training centres, measured in training scales."]'::jsonb, 3, 'The row''s raw values, GR 48.200000, RHOB 2.348000 and NPHI 0.243000, are each below the training centres 59.844500, 2.391150 and 0.255072, so each z is negative, and each is well under one training scale away. A negative z is an ordinary value. The scaler uses the training parameters unchanged and computes nothing from the test well itself.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 7, 'After the training scaler is applied to the 90 test rows of the teaching split, do the test rows come out with centre 0 and scale 1?', '["Yes; applying the scaler recentres any rows it is given, so every set of rows comes out at centre 0 and scale 1.", "No; they land wherever the training centres and scales put them, which shows where the test wells sit.", "Yes, once the engine refits the scale on the test rows, which it does to keep all the z values comparable.", "Only GR does, since the gamma ray is the one log whose training and test centres happen to agree."]'::jsonb, 1, 'The parameters are fitted on the training rows and applied unchanged, so only the training rows come out with centre 0 and scale 1. The test rows come out wherever those parameters put them, which is informative about the test wells. The basis says, in the engine''s words, "standard scaler fitted on 180 training rows; parameters unchanged". Nothing is refitted on the test rows.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 8, '`fitStandardScaler` is fitted on EKENE-1''s 30 rows with GR and mudWeight and refuses on `X.mudWeight`. On the nine sonic wells the same feature is accepted. Why?', '["The engine refuses a well-level attribute whenever fewer than 180 training rows are passed to the scaler with it.", "Mud weight is missing on EKENE-1, and the nine-well fit simply skips over the rows where the value is null.", "Mud weight is constant down a well, so it has zero variance on one well''s rows and varies across nine.", "Any feature measured in ppg is refused until it is converted to a unit the scaler lists."]'::jsonb, 2, 'The engine''s own words are: "X.mudWeight has zero variance on the 30 training rows (every value is 9.4): standardising would divide by zero, so drop the feature or fit on rows where it varies". A feature is refused as constant only when every training value is identical, so whether it is refused is a statement about the training rows. The refusal has no row-count rule and no unit rule, and EKENE-1''s mud weight is present on every row.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 9, 'Min-max scaling fitted on the nine sonic wells maps EKENE-6''s highest gamma ray to 1.219324. What is the engine telling you?', '["The scaler has failed, since a min-max value must lie in [0, 1], and the row should have been refused.", "That value was clipped to the nearest allowed figure after rounding and lies inside the training range.", "EKENE-6 was fitted on its own rows, so its own maximum maps to 1.219324 by the scaler''s design.", "That row reads above the training maximum of 120.870000 gAPI, and the scaler leaves it unclipped so the fact shows."]'::jsonb, 3, 'Min-max maps the training minimum to 0 and the training maximum to 1 and does not clip a new row. The basis says, in the engine''s words, "none: a new row outside the training range maps outside [0, 1]". EKENE-6''s gamma ray is above the nine-well maximum on 4 of its 30 rows, and a scaled value above 1 marks a row outside the range the model was fitted on. EKENE-6 has no sonic, so it trains nothing here.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 10, 'EKENE-6''s gamma ray is raised by 30 gAPI on all 30 of its rows, yet min-max flags only 4 rows above 1. What does that show?', '["A range check sees only rows that leave the training range; the rest are shifted and still inside it.", "Only 4 rows were raised by the hot shale, and the other rows of EKENE-6 read an ordinary gamma ray for the rock.", "The scaler clipped the rest back to 1, so only the 4 rows it could not clip are left above 1.", "Min-max compares each row with EKENE-6''s own maximum, which only its 4 highest rows are able to exceed."]'::jsonb, 0, 'The hot shale raises every EKENE-6 gamma ray by the same 30 gAPI. Only 4 rows end up above the training maximum of 120.870000 gAPI; the others are raised too but still fall inside the range, so min-max maps them between 0 and 1 and raises no flag. The scaler clips nothing, and it is fitted on the nine sonic wells, never on EKENE-6.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 11, 'On the one-well workflow, with EKENE-8 held out, least squares is fitted on the raw logs and again on standardised logs. How far apart are the two sets of predictions for EKENE-8?', '["Several us/ft, since standardising changes every coefficient and so moves every prediction along with them.", "They differ by the ratio 1.002789, because the scaler divides each feature by its population spread.", "At most 1.42e-14 us/ft, which is rounding: with an intercept, least squares gives the same plane under any rescaling.", "They cannot be compared, because a model fitted on standardised features cannot predict raw rows."]'::jsonb, 2, 'The predictions differ by at most 1.42e-14 us/ft, which is rounding. The coefficients do change, because they change units, but the fitted plane is the same, so scaling leaves this model''s predictions alone. 1.002789 is the ratio of the sample to the population scale on 180 rows, and a standardised model predicts any row once the same training scaler is applied to it.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 12, 'A colleague fits the standard scaler on all 270 sonic rows before splitting. For this tier''s least squares model the test RMSE then moves only by rounding. Is the procedure acceptable?', '["Yes: a change that small cannot matter, so the order of splitting and scaling is a matter of taste.", "No: the scaler''s numbers were computed partly from the test wells, and the procedure is the defect whatever its size.", "Yes, as long as the population standard deviation is used, since dividing by n makes the scaler independent of the rows.", "Only with the sample standard deviation, because dividing by n - 1 corrects for the extra test rows."]'::jsonb, 1, 'Every number in a scaler fitted on all 270 rows was computed partly from EKENE-4, EKENE-5 and EKENE-8, the wells the split promised to keep unseen. Least squares with an intercept happens to hide it, but models whose answers depend on the scale do not, so the habit is learned here: split first, then fit anything with parameters on the training rows alone. Neither divisor makes a scaler independent of the rows it was fitted on.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 13, 'A scaler fitted on GR and RHOB is applied to rows carrying GR, RHOB and NPHI. What comes back?', '["Scaled GR and RHOB, with NPHI passed straight through in its raw unit at the end of each row.", "All three scaled, with NPHI taking the centre and scale of the last feature that was fitted.", "Three scaled columns, with NPHI fitted afresh on the very rows that are being transformed.", "A refusal on `X`, whose message is \"X must have 2 columns, as the scaler was fitted on\"."]'::jsonb, 3, '`applyScaler` checks the shape of what it is handed and refuses rows with a different number of columns from the fit, on the field `X`. It never passes a column through untouched, borrows another feature''s parameters or fits anything new: the parameters it applies are the ones fitted on the training rows, unchanged.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 14, '`fitMinMaxScaler` is fitted on 2 training rows whose CALI both read 3. What does it return?', '["A refusal on `X.CALI`: the range is zero, so min-max scaling would divide by zero.", "CALI scaled to 0 on both rows, since the training minimum always maps to 0 by definition.", "Both rows set to one half, the midpoint the engine takes whenever the training range vanishes.", "A scaled CALI of 1 on both rows, as the training maximum always maps to 1 by definition."]'::jsonb, 0, 'Min-max divides by the training range, maximum less minimum, and here it is zero. The engine''s own words are: "X.CALI has zero range on the 2 training rows (every value is 3): min-max scaling would divide by zero, so drop the feature or fit on rows where it varies". It returns no scaled value at all, and it has no midpoint rule.'),
  ('mlcore', 'beginner', 'module', 'm03-scaling-on-the-training-rows', 15, 'On the one-well workflow, EKENE-8 held out, the standardised least squares fit gives GR a coefficient of 6.898926. In what unit is that?', '["us/ft per gAPI, the unit of the raw GR coefficient, since standardising leaves a unit as it was.", "gAPI per us/ft, since a standardised fit reverses which log is read against which.", "us/ft per population standard deviation of GR over the 240 training rows.", "A unitless share of DT''s own spread, since both sides of the fit were standardised first."]'::jsonb, 2, 'Only the features are standardised; the target stays DT in us/ft. So a standardised coefficient reads in us/ft per population standard deviation (divisor n) of its feature over the training rows, here the 240 rows of the eight training wells. The raw GR coefficient of that fit, 0.320501, is the one in us/ft per gAPI.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 1, 'What does least squares make as small as it can on the training rows?', '["The sum of squared residuals, sum (y - yhat)^2.", "The sum of the absolute residuals, which is why its training score is the MAE of the rows.", "Its largest single residual, so that no training row is missed by much more than the rest.", "How many rows the plane misses by more than one residual standard error."]'::jsonb, 0, 'Least squares finds the coefficients that make sum (y - yhat)^2 as small as it can be: 5967.842781 on the 180 training rows of the teaching split, and no other intercept and three coefficients give a smaller sum on those rows. It does not minimise absolute misses, the largest miss or a count of rows; MAE is a score computed afterwards.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 2, 'The teaching fit gives GR a coefficient of 0.288005 us/ft per gAPI. How does the course read it?', '["One more gAPI moves the measured DT by 0.288005 us/ft in every well of the field, whatever the other logs do.", "GR explains 0.288005 of the variation in DT about the training mean.", "Holding RHOB and NPHI fixed, one more gAPI moves the fitted DT by 0.288005 us/ft.", "It marks GR as the least important feature, its coefficient being smallest."]'::jsonb, 2, 'A coefficient is a rate on the fitted target with every other feature pinned: us/ft per gAPI, holding RHOB and NPHI fixed. It describes the plane fitted to these rows, so it says nothing about the measured DT in every well, and it is no share of variation (that is R-squared''s job). Its size says nothing about importance until the feature''s spread is known: a gAPI is a small unit.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 3, 'NPHI''s coefficient in the teaching fit is 138.783590 us/ft per v/v. By how much does one porosity unit, 0.01 v/v, move the fitted DT, holding the others fixed?', '["138.783590 us/ft, since the coefficient already reads per porosity unit of 0.01 v/v.", "1.387836 us/ft, the coefficient over 100.", "11.127468 us/ft, the NPHI coefficient per hundredth once the other two logs are dropped.", "0.288005 us/ft, the same as one gAPI of gamma ray, since both are per unit of a log."]'::jsonb, 1, 'NPHI is a fraction, so its coefficient is per whole unit of v/v, a porosity of one. Per 0.01 v/v it is 138.783590 over 100, which is 1.387836 us/ft. 11.127468 is the NPHI coefficient of a different fit, NPHI alone, and still per whole v/v. 0.288005 is GR''s coefficient, per gAPI.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 4, 'Fitted on NPHI alone over the same 180 training rows, the NPHI coefficient is 11.127468; beside GR and RHOB it is 138.783590. Which reading is right?', '["The single-feature figure, because GR and RHOB distort the NPHI coefficient once they join the fit.", "The three-feature figure, because the single-feature fit has a training R-squared of only 0.001327.", "Neither, since the NPHI coefficient is the mean of the two fits, weighted by how many rows each used.", "Both, each for its own feature list: the second holds GR and RHOB fixed, and the first has no others to hold."]'::jsonb, 3, 'The NPHI column is identical in both fits. Beside GR and RHOB its coefficient describes how DT moves with NPHI while the other two are held fixed; on its own it describes something else. Neither is wrong, and a low R-squared does not make a coefficient false. So a coefficient is quoted with its features, its rows and its unit. No averaging of fits is involved.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 5, 'The teaching fit''s intercept is -0.552686 us/ft with a standard error of 30.261214. What is it?', '["The sonic slowness of a rock with no porosity, measured by the fit to within 30.261214 us/ft.", "The mean training DT, since the intercept centres the plane on the rows it was fitted on.", "It is the average residual of the fit, which least squares drives to a value near zero.", "The fitted DT where every feature is zero: a point far outside the data that frees the plane from the origin."]'::jsonb, 3, 'The intercept is the fitted DT at zero gamma ray, zero density and zero porosity, a row no rock supplies. It is there so the plane need not pass through the origin, and its large standard error says the data pin it down poorly. It is no rock property, the mean training DT is 105.883333 us/ft, and the residuals, which average close to zero, are a different quantity from the intercept.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 6, 'NPHI''s coefficient, 138.783590, is far larger than GR''s, 0.288005. What does that say about which feature matters more?', '["NPHI matters far more, since a larger coefficient moves the prediction further on every row.", "Nothing yet: a coefficient''s size depends on its feature''s unit and spread, which must be known first.", "GR matters more, since a small coefficient marks a feature the plane can lean on without large corrections.", "They matter equally, since least squares scales each coefficient so every feature pulls the same weight."]'::jsonb, 1, 'A coefficient carries the target''s unit over the feature''s unit. NPHI''s is large because a whole v/v is a large step, and GR''s looks small because a gAPI is small. Its size says nothing about importance until the feature''s own spread is known, and least squares does no rescaling of its own. Importance is measured directly with a stated method in a later tier.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 7, 'The teaching fit has 180 rows, three features and an intercept. How many residual degrees of freedom does it have?', '["176, since n - p counts the intercept among the 4 coefficients.", "179, the n - 1 that the sample standard deviation divides by on 180 rows.", "180, since degrees of freedom count the rows, and the coefficients use none of them.", "90, since the residual degrees of freedom are the rows held back to test the fit."]'::jsonb, 0, 'The residual degrees of freedom are n - p, with p counting the intercept: 180 - 4 = 176, as the engine prints. Each coefficient the fit estimates uses up one row''s worth of freedom. 179 is the sample divisor on 180 rows and has nothing to do with the coefficients, and the 90 test rows are not part of this fit at all.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 8, 'On the 180 training rows the residual standard error is 5.823075 us/ft and the training RMSE is 5.758010. Why is s the larger of the two?', '["s is measured on the test wells, whose misses run larger than the misses on the training rows.", "s squares each miss twice before it takes the root, so it reads above the RMSE of the same rows.", "Both root the same RSS, but s divides it by n - p = 176 and RMSE by n = 180.", "RMSE drops the intercept''s residual first, which lowers it below s."]'::jsonb, 2, 's^2 = RSS / (n - p) and RMSE^2 = RSS / n, on the same RSS of 5967.842781, so the smaller divisor gives the larger figure. Dividing by n - p allows for the coefficients the fit spent on making those misses small. Both are training figures, neither squares twice, and no residual is dropped; the test RMSE, 4.282693, is smaller than both.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 9, 'The teaching fit''s RSS is 5967.842781 and its TSS about the training mean is 18853.190000. Which R-squared follows, and how is it named?', '["0.683457, the R-squared of the training fit about the training mean.", "0.815322, the R-squared of the training fit taken about the mean of the test targets.", "0.678062, the R-squared of the training fit with no adjustment for the coefficients spent.", "0.816151, which this RSS gives for the test wells about the training mean."]'::jsonb, 0, 'The training R-squared is 1 - RSS / TSS on the 180 rows that chose the plane: 0.683457, named in full as the training fit about the training mean. 0.815322 and 0.816151 are the test wells'' R-squared values, about the test mean and about the training mean, and they use the test rows'' own squared misses. 0.678062 is the adjusted R-squared, the version that is corrected for the coefficients.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 10, 'Beside the training R-squared of 0.683457 the engine prints an adjusted R-squared of 0.678062. What is the adjusted figure?', '["The R-squared of the three test wells, adjusted to the training mean so the two can be compared.", "The training R-squared once the intercept is removed from the fit.", "It is the training R-squared recomputed with the sample standard deviation in place of the population one.", "The same training R-squared, corrected for the number of coefficients the fit spent."]'::jsonb, 3, 'The adjusted R-squared is the same idea as the training R-squared, measured on the same 180 rows, corrected for the coefficients the fit spent. The test R-squared about the training mean is 0.816151, a different figure. No intercept is removed, and no scaler divisor enters an R-squared.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 11, 'The standard error formula behind GR''s 0.066103 assumes independent residuals. Why does the course say the printed standard errors are exact only under that assumption?', '["The standard errors are computed on the test wells, whose residuals depend on the training fit.", "Least squares forces each well''s residuals to sum to zero, which ties them together row by row.", "Rows of one Ekene well share its sonic offset, so residuals within a well are not independent.", "GR, RHOB and NPHI are logged on one tool string, so their errors are shared by construction."]'::jsonb, 2, 'The basis states the formula, s x sqrt(diag((X''X)^-1)) with s^2 = RSS / (n - p), and it assumes residuals independent row to row. Each Ekene well carries its own offset, so its residuals sit above or below the plane together. The standard errors are training figures. Least squares balances the residuals over all the fitted rows, never well by well, and no shared tool error is part of the Ekene field.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 12, 'In the teaching fit, GR''s t value is 4.356927 and RHOB''s is 1.830825. What is a t value?', '["The coefficient times its standard error, a measure of how far the prediction moves per unit of log.", "The coefficient divided by its standard error: a reading of the coefficient against its own uncertainty.", "The share of DT''s variation that each feature explains on its own, scaled up by the number of training rows used.", "How many training wells keep the coefficient''s sign when the fit is repeated one well at a time."]'::jsonb, 1, 'A t value is the coefficient over its standard error: GR''s 0.288005 over 0.066103 gives 4.356927, several standard errors from zero, and RHOB''s 1.830825 is closer to zero. It is read under the formula''s assumptions. It is no product, no share of variation and no count of wells.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 13, 'Why does the engine refuse a least squares fit when the rows equal the coefficients, n = p?', '["The design becomes a column of zeros, and a zero column''s coefficient cannot be identified.", "The plane passes through every row, leaving no residual degree of freedom to estimate s from.", "With n = p the target has zero variance, so the R-squared of the fit would divide by zero.", "Least squares needs at least 30 rows, one well''s worth, before it can estimate any coefficient."]'::jsonb, 1, 'With n = p the plane passes through every row exactly, every residual is zero, and n - p leaves nothing to measure the misses with. The fit would look perfect and say nothing. The engine refuses n <= p and names `X`. A zero column and a constant target are separate refusals with their own fields, and the rule is n - p at least 1, with no fixed row minimum.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 14, 'A CALI column that is zero on every row is passed to `ols`. What does the engine return, and why?', '["A coefficient of zero for CALI, since a column of zeros can only ever contribute nothing to the plane.", "A fit with CALI dropped without notice and three features reported in the basis block of the result.", "A CALI coefficient equal to the intercept, since both of them multiply a constant column in the design.", "A refusal on `X.CALI`: its coefficient could take any value without changing a prediction, so it is not identifiable."]'::jsonb, 3, 'The engine''s own words are: "X.CALI is zero in every row, so its coefficient is not identifiable". Any value of that coefficient gives the same predictions, so the engine cannot choose one and returns none. It drops no feature silently, and the intercept''s column is ones, which a column of zeros does not match.'),
  ('mlcore', 'beginner', 'module', 'm04-ordinary-least-squares', 15, 'The teaching split trains on 180 rows, far more than its 4 coefficients. What does that row rule leave for you to check?', '["How many wells the rows come from: 180 rows from six wells is little independent evidence.", "Nothing more, since the engine''s rule that n exceeds p already guarantees the evidence is enough.", "Whether the rows number 30 times the coefficients, which the engine leaves to you.", "That every row comes from a different well, which the splits make certain."]'::jsonb, 0, 'The engine checks rows, because rows are what least squares counts. Rows inside a well share its offset, so a model can clear the row rule easily and still have seen very few independent wells. Counting wells is the caller''s job, and it is why the course states wells beside rows. No thirty-times rule exists, and a whole-well split keeps a well''s rows together.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 1, 'Which statement about RMSE and MAE on the test wells is right?', '["RMSE reads in us/ft, and MAE is a unitless fraction of the variation about the mean of the test targets.", "Both are fractions of the variation about a reference mean, so each has to name its reference when quoted.", "Both read in us/ft; RMSE squares each miss before averaging and rooting, and MAE averages the size of each miss.", "MAE squares each miss while RMSE takes it at face value, so it is MAE that weighs a large miss more."]'::jsonb, 2, 'RMSE = sqrt(sum (y - yhat)^2 / n) and MAE = sum |y - yhat| / n, both in the target''s unit, us/ft. They need no reference to be read. R-squared is the score that is a fraction of variation about a reference mean. It is RMSE that squares the misses.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 2, 'A few rows of a well are badly predicted while the rest are close. Which score rises more?', '["RMSE, because it squares each miss before averaging, so a large miss counts for more.", "MAE, since it takes every miss at face value and so cannot hide a large one inside an average.", "Neither moves more than the other, since both average the same misses over the same rows.", "R-squared, which alone of the scores is built from squared misses and so follows the large ones."]'::jsonb, 0, 'RMSE squares each miss before averaging, so one large miss counts for more in it than several small ones of the same total size; MAE takes every miss at face value. When a few rows are badly predicted, RMSE rises more than MAE. The two average the same misses in different ways, and RMSE is built from squared misses as surely as R-squared is.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 3, 'On the teaching split the test RMSE is 4.282693 us/ft and the training RMSE is 5.758010. How can a model score better on wells it never saw?', '["The test RMSE divides by its 90 rows and the training RMSE by 180, which keeps the test figure smaller than the training one.", "Through the scaler the model saw the test wells, which pulled them onto the fitted plane.", "It cannot: a test RMSE below the training RMSE shows the split leaked, so the fit must be redone.", "The three held-out wells happen to sit close to the plane; a training score is no ceiling on a test score."]'::jsonb, 3, 'Least squares makes the training misses as small as a plane can, but the training wells may simply be harder to fit than the test wells, and which wells land on which side is the draw. The held-out wells score 4.620664, 4.627312 and 3.501687 on their own. RMSE is a root mean, so its row count does not shrink it. This fit uses no scaler, and a whole-well split shares no well.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 4, 'On the three test wells, R-squared is 0.815322 about the test mean and 0.816151 about the training mean, while the RMSE is 4.282693 both times. What changed between the two R-squared values?', '["Refitted predictions, since the model is fitted again about each reference mean before the score is taken.", "Only the reference in the denominator; the misses in the numerator are identical.", "The rows, since the second value adds the 180 training rows to the 90 test rows it scores.", "Each miss, since the training mean is subtracted from every prediction before it is scored."]'::jsonb, 1, 'R-squared = 1 - SSE / sum (y - reference)^2. The SSE is the same, which is why RMSE and MAE are unchanged at 4.282693 and 3.526103; only the reference mean in the denominator moved, from 105.214444 to 105.883333 us/ft. Nothing is refitted, both are scored on the same 90 test rows, and the predictions are untouched.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 5, 'When `regressionMetrics` scores the test wells with no `referenceMean`, which mean is R-squared taken about?', '["The mean of the test targets themselves, 105.214444 us/ft, as scikit-learn''s r2_score does.", "The training mean, 105.883333 us/ft, since a new well is judged against the training average.", "Zero, since R-squared without a reference compares the misses with the raw sizes of the targets.", "The mean of the predictions, so that R-squared measures how the plane varies about itself."]'::jsonb, 0, 'The default reference is the mean of the test targets, and the basis says, in the engine''s words, "1 - SSE / sum (y - mean of these y)^2 (scikit-learn r2_score); negative when worse than that mean". The training mean, 105.883333, is used only when it is passed as `referenceMean`, the out-of-sample convention. Neither zero nor the mean of the predictions is a reference the engine uses.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 6, 'The engine''s own case sets true values 1, 2, 3 against predictions 3, 2, 1 and returns R-squared -3.000000. What does a negative value mean?', '["The engine has made an error, since R-squared is a share of variation and must lie between 0 and 1.", "The predictions run the wrong way, and its size, 3.000000, is the figure a report should quote.", "The predictions do worse than the reference mean would; R-squared has no lower bound.", "The RMSE with a sign attached, the misses being two, zero and two."]'::jsonb, 2, 'R-squared is not bounded below. A negative value is a real result: the predictions do worse than simply predicting the reference mean. The engine prints it as it is, and a report quotes it as it is, sign and all. The RMSE of that case is 1.632993 and its MAE 1.333333, separate scores.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 7, 'A test set whose DT reads the same on every row is scored with `regressionMetrics`. What happens?', '["R-squared comes back as 0, since the predictions can explain none of a variation of zero.", "It returns an R-squared of 1, since every prediction then misses the mean by the same amount.", "RMSE and MAE are returned with R-squared left out, and a note is added to the basis block.", "A refusal on `yTrue`: with zero variance, R-squared about its mean is undefined."]'::jsonb, 3, 'The engine''s own words are: "yTrue has zero variance (every value is equal), so R-squared about its mean is undefined". The denominator of R-squared about the test mean would be zero, so the engine returns no score at all. It does not substitute 0 or 1, and it does not return part of a result.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 8, 'Scored well by well, the teaching split''s test wells read RMSE 4.620664 (EKENE-4), 4.627312 (EKENE-5) and 3.501687 (EKENE-8). What is the pooled test RMSE of 4.282693?', '["The plain mean of the three well RMSEs, which weighs each well equally whatever its misses.", "A figure over all 90 rows together, in which a well with larger misses pulls the pool up.", "The RMSE of the middle well, which the engine reports as the typical well of the three.", "EKENE-8''s RMSE rounded up by the pooling of all the rows into one figure."]'::jsonb, 1, 'The combined test RMSE pools the squared misses of all 90 rows before the root, so each row counts once and a well with larger misses pulls it up. It is no average of the three well RMSEs and no single well''s score. Each well''s own RMSE is a statement about that well.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 9, 'Least squares fitted on all 270 sonic rows leaves EKENE-9''s residuals averaging 6.733268 us/ft and EKENE-2''s averaging -5.829469. What does that show?', '["Those two wells hold outliers the fit could not reach, which should be removed before any refit.", "The fit is biased high, since the residuals stop summing to zero once an intercept is included.", "The two wells were logged in different units of slowness, which one plane cannot reconcile.", "Each well sits above or below the plane as a block, which a pooled score such as RMSE hides."]'::jsonb, 3, 'Grouping the residuals by well shows what the score hides: each well sits above or below the plane as a block. In the Ekene field the cause is the sonic offset each well adds to every DT sample. The residuals of the fitted rows still sum to zero overall, -1.99e-12 us/ft, which is rounding. Every well''s DT is in us/ft, and nothing here marks a row as an outlier.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 10, 'Across the nine sonic wells, the well mean residuals of the 270-row fit run from EKENE-2''s -5.829469 up to EKENE-9''s 6.733268. What is their span, and what drives it?', '["12.562737 us/ft, driven by the sonic offset each well adds to every DT sample.", "0.637253 us/ft, the largest gap between a well''s mean residual and its planted offset.", "5.333216 us/ft, the residual standard error, which sets how far apart the wells can sit.", "0.728027, the fit''s R-squared, which is the measure of how far apart the wells sit."]'::jsonb, 0, 'The well means span 12.562737 us/ft from the lowest to the highest, and each well''s mean tracks its planted offset. 0.637253 is the largest gap between a mean residual and its planted offset, the check that the method recovers the structure. 5.333216 is the residual standard error of the fit and 0.728027 its R-squared; neither measures the spread of the wells.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 11, 'The course prints each well''s planted offset, less the nine-well mean, beside its mean residual, and the largest gap is 0.637253 us/ft, for EKENE-7. What does the check show, and why can it be made at all?', '["The fit is wrong for EKENE-7, whose offset should be taken out of its data before the model is refitted.", "The mean residual per well recovers the planted structure closely; only a synthetic field comes with offsets to compare.", "Every real field carries a stated offset per well, and the check compares the fit with that record.", "The engine reads the planted offsets and corrects the fit with them, so the gaps show what it missed."]'::jsonb, 1, 'The largest gap between a well''s mean residual and its planted offset is 0.637253 us/ft, so grouping residuals by well recovers the planted blocks closely. The offsets are printed less the nine-well mean because the intercept absorbs that mean. No real field comes with such a column, and the engine never sees it: the check is possible only because the Ekene field was drawn with the structure on purpose.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 12, 'With an intercept, the residuals of the 270-row fit sum to -1.99e-12 us/ft. What does that figure mean?', '["Each well''s residuals also sum to zero, so no well sits above or below the plane on average, however its rows were drawn.", "The fit carries a small bias of -1.99e-12 us/ft per row, which should be added to each prediction.", "Zero up to rounding: the plane balances its fitted rows as a whole, though whole wells still sit above or below it.", "The intercept was dropped, since only a fit through the origin leaves residuals that small."]'::jsonb, 2, 'With an intercept the residuals of the fitted rows sum to zero up to rounding, and -1.99e-12 us/ft over 270 rows is rounding in the arithmetic. It says the plane misses high as much as it misses low, in total. It says nothing of each well: the well means run from -5.829469 to 6.733268. The intercept is what makes the total zero.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 13, 'The 270-row fit reports R-squared 0.728027 about its own mean and a residual standard error of 5.333216 us/ft. What do those two figures say about the well blocks?', '["Nothing: only grouping the residuals by well shows that the misses are organised by well.", "That no blocks exist, since an R-squared that high is impossible with wells sitting off the plane.", "That the blocks span 5.333216 us/ft, since s is the typical distance of a well from the plane.", "Every well is fitted to within 0.728027 us/ft, the R-squared read as a typical miss."]'::jsonb, 0, 'The fit looks ordinary, and nothing in its R-squared or its residual standard error says the misses are organised by well. Grouping the residuals shows it: the well means span 12.562737 us/ft. s is the typical size of a row''s miss, and R-squared is a fraction, never a distance in us/ft.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 14, 'Three R-squared values belong to the teaching fit: 0.683457, 0.815322 and 0.816151. How must each be quoted?', '["As one figure, their average, since all three belong to the one fitted plane and describe the same model.", "By the largest alone, 0.816151, since a report should show the model at its best and leave the rest out.", "By the training value alone, since a test R-squared depends on a reference mean and so cannot be trusted.", "With its rows and its reference mean: training rows about the training mean, test wells about the test mean, test wells about the training mean."]'::jsonb, 3, 'The course''s rule for the word: an R-squared names its rows and its reference mean. 0.683457 is the training fit about the training mean; 0.815322 the test wells about the test mean; 0.816151 the test wells about the training mean. Averaging them mixes different rows and yardsticks, and choosing one silently hides what it measured. A test R-squared is trustworthy once its reference is named.'),
  ('mlcore', 'beginner', 'module', 'm05-fit-metrics-and-residuals', 15, 'About each well''s own mean, EKENE-8 reads R-squared 0.855184 and EKENE-4 reads 0.735001, with RMSEs of 3.501687 and 4.620664. What does a per-well R-squared compare?', '["Its misses against the training misses, so a value above the training R-squared marks a better well.", "That well''s misses with the spread of its own DT about its own average, so it depends on how much the well varies.", "The well''s RMSE against the pooled test RMSE of 4.282693, taken as the ratio of the two figures on the 90 test rows.", "Its mean residual against its planted offset, which is why each well is given its own value."]'::jsonb, 1, 'About a well''s own mean, R-squared compares the well''s squared misses with the spread of its measured DT about its own average, so the same misses read as a higher R-squared in a well whose sonic varies more. RMSE needs no reference. Neither the training misses, the pooled RMSE nor a planted offset enters the per-well figure.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 1, 'The one-well workflow makes five calls: split, fit, predict, score the held-out well, score the training rows. Why must the split come first?', '["The engine demands it, since `ols` refuses any rows that did not arrive through a split call first.", "It decides which rows may shape anything fitted later, so no fitted number has seen the held-out well.", "Splitting after the fit would change the coefficients, since least squares refits on the rows it scores.", "A later split draws a fresh seed each time, so the same well could never be held out twice in a row."]'::jsonb, 1, 'The split decides which rows are allowed to influence anything. Every later step either fits on the training rows or is applied to the held-out well, so a scaler, a feature choice or any other fitted number computed before the split has let the held-out well shape the model. `ols` takes whatever rows it is given, scoring never refits a model, and the seed is whatever the caller states.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 2, '`groupSplit` is called on the nine sonic wells with nTestGroups 1 and seed 5. What does it hand back?', '["Three test wells, EKENE-4, EKENE-5 and EKENE-8, since seed 5 always holds out the teaching split''s wells.", "A refusal, since nTestGroups 1 leaves too few test rows for least squares to be scored on a well.", "One test well, EKENE-1, the first name of the sorted list, with 240 rows left to train the model.", "One test well, EKENE-8, with its 30 rows, and 8 training wells with 240 rows."]'::jsonb, 3, 'nTestGroups 1 asks for exactly one well, the first of the shuffled order, and at seed 5 that order begins with EKENE-8. All 30 of its rows go with it and the other eight wells train on 240 rows. The teaching split holds out three wells because its size comes from the fraction 0.3. EKENE-1 heads the sorted list only before the shuffle, and one well of 30 rows is scored without complaint.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 3, 'The one-well workflow prints two R-squared values, 0.709438 and 0.832560. How is each one named?', '["0.709438 is the training fit about the training mean; 0.832560 is EKENE-8 about its own mean.", "0.709438 is EKENE-8 about the training mean; 0.832560 is the same well about the mean of its own DT.", "Both belong to EKENE-8, the first before the scaler is applied and the second after the scaler is fitted.", "Either may be quoted for this model, as both describe the one plane fitted to eight wells."]'::jsonb, 0, '0.709438 is the R-squared of the fit on its 240 training rows about the training mean, the figure step 2 and step 5 both print. 0.832560 is taken on EKENE-8''s 30 rows about EKENE-8''s own mean, the engine''s default for a test score. Scaling leaves a least squares plane unchanged, and the two figures describe different rows against different references, so each is quoted with both named.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 4, 'With EKENE-8 held out, the training rows score an RMSE of 5.462405 us/ft and EKENE-8 scores 3.765285. What may a report conclude?', '["That the model will do better on new wells than on its training wells, as the lower RMSE shows.", "That the split leaked, since a held-out well cannot score better than the rows that fitted the plane.", "That EKENE-8 happens to sit close to this plane; the figure describes that one well on this draw.", "That the training RMSE is inflated by rounding, and the two figures agree once both are rounded to two places."]'::jsonb, 2, 'The held-out well scores better than the training rows on this draw, as the teaching split''s three test wells did. That is a fact about EKENE-8 and seed 5. A single well is one reading, and other wells score worse: EKENE-2 reads 7.260092 us/ft. A whole-well split shares no well, and the gap between 3.765285 and 5.462405 is far larger than rounding.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 5, 'Held out one at a time, five wells score RMSEs from 3.564857 us/ft (EKENE-3) to 7.260092 (EKENE-2). How should one of them be quoted?', '["With its well and its seed: each is how the model did on that one well.", "As the model''s RMSE, since any one held-out well gives a fair and complete test of the fitted model.", "By the lowest, 3.564857, since the seed can be chosen and a report should show the model at its best.", "By their plain average only, since a single well is too small for its RMSE to be meaningful at all."]'::jsonb, 0, 'The same model form, fitted on eight wells each time, misses a new well by an amount that depends on the well. A figure quoted alone, without its seed and its well, claims more than it knows. Choosing the seed with the best score hides the other wells, and a single well''s RMSE is a real reading of that well; it simply is not the whole story.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 6, 'EKENE-3 reads RMSE 3.564857 us/ft and R-squared 0.736197 about its own mean; EKENE-8 reads RMSE 3.765285 and R-squared 0.832560. How can the well with the smaller misses read the lower R-squared?', '["The two R-squared values use different references, EKENE-3 the training mean and EKENE-8 its own mean.", "It cannot, so one of the two held-out fits must have been scored on the training rows by mistake.", "R-squared rises with the RMSE, so the well with the larger misses must also read the higher R-squared.", "EKENE-3''s own DT varies less about its mean, so misses of a similar size are a larger share of its spread."]'::jsonb, 3, 'About a well''s own mean, R-squared compares the well''s squared misses with the spread of its measured DT about its own average. EKENE-3''s misses are slightly smaller, yet they take a larger share of a smaller spread, so its R-squared is lower. Both figures are about each well''s own mean. R-squared falls as the misses grow against a fixed spread, and RMSE needs no reference at all.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 7, 'With EKENE-8 held out, the GR coefficient is 0.320501 us/ft per gAPI; the teaching fit, three wells held out, gives 0.288005. Why do they differ?', '["One of the two was fitted on standardised logs, and standardising changes the coefficient''s unit.", "Each is fitted on a different set of training wells, eight in one and six in the other.", "The seed enters the least squares sums, so a new seed gives a new coefficient.", "The teaching fit is wrong, since only the fit with the most training wells gives GR''s true coefficient."]'::jsonb, 1, 'The two fits use different rows: eight training wells, 240 rows, against six, 180 rows. A coefficient describes the plane fitted to its rows, so it moves when the wells change, and fitting on different wells shows that movement directly. Both are raw fits in us/ft per gAPI. The seed only chooses the wells, and neither figure is the true one.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 8, 'The table of held-out wells lists seeds 1, 2, 3, 4 and 6. Why does seed 5 not appear?', '["A refusal: seed 5 cannot be paired with nTestGroups 1, since the seed and the size are fixed together for this split.", "The course never ran it, keeping seed 5 for the teaching split with three wells held out.", "It holds out EKENE-8, which seed 1 already holds out, and the table lists the first seed for each well.", "EKENE-6 is what it holds out, the well with no sonic, so there is no measured DT to score against."]'::jsonb, 2, 'The table lists the first seed that holds out each of five different wells. Seed 5 holds out EKENE-8, the same well as seed 1, so it would add no new row; it is in fact the seed of the workflow''s own first step. No seed is refused for a size, and EKENE-6 is never among the nine sonic wells a sonic split draws from.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 9, 'A write-up of the teaching fit gives the split as `groupSplit`, test fraction 0.3, seed 5. Why does the course also ask for the names of the wells on each side?', '["Because the engine''s seeds can change between runs, so the seed may not reproduce the same wells.", "So the test fraction is on record, since a seed and a split name leave the fraction out of a write-up.", "The seed alone tells a reader nothing about which wells were held out until the call is run again.", "Because a named well list lets the reader skip the split, since the fit can then be copied directly."]'::jsonb, 2, 'The seed fixes the draw, and anyone with the same wells and the same call gets the same wells back. But a reader cannot see from the number 5 that EKENE-4, EKENE-5 and EKENE-8 were the test wells without rerunning the call, and row counts beside well counts show how much evidence the fit rests on. The fraction, 0.3, is already written beside the seed. A seeded draw repeats exactly, and the well list replaces neither the split nor the fit.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 10, 'Which sentence belongs in a write-up of a least squares fit to the Ekene wells?', '["The field is synthetic, so any check against a planted value is one no real field allows.", "The test RMSE of 4.282693 us/ft is the error on any new well of the field.", "The standard errors are exact, as 180 rows far outnumber 4 coefficients.", "The coefficients rank the logs by importance, with NPHI''s 138.783590 by far the most important log."]'::jsonb, 0, 'The course asks for three sentences on what the numbers do not claim: the test score is one draw of wells, the standard errors assume independent residuals that rows of one well do not give, and the field is synthetic. A test RMSE describes the wells it was measured on, the row count does not make residuals independent, and a coefficient''s size depends on its feature''s unit.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 11, 'On the way to a fit, the scaler refused a feature that was constant on the training rows, and you dropped it. What does the course ask the write-up to do?', '["Keep the feature listed with a coefficient of zero, which is how least squares treats a constant.", "Refit on all rows so that the feature varies, and report that fit so the refusal does not recur.", "Leave it out entirely, since a refused call produced no result and so has nothing to report.", "Record the refusal and the decision taken, so a reader who reruns the work knows why the feature went."]'::jsonb, 3, 'A reader who reruns the work will meet the same refusal, and a note of what was decided tells them. Leaving it out hides a choice that changed the model. A dropped feature has no coefficient at all, and fitting on every row to dodge the refusal would let the held-out wells shape the scaler.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 12, 'In the Ekene field, which method finds the well-level sonic offset each well adds to its DT samples?', '["Min-max scaling fitted on the nine sonic wells, which maps the offset rows above 1.", "The mean least squares residual of each well, with the logs alone as features.", "The refusal `ols` gives at the first null target, which names the well by its row.", "The pay rule, since a well with a larger offset carries more pay rows than the others."]'::jsonb, 1, 'Grouping the residuals of a fit on the logs alone by well shows each well sitting above or below the plane as a block, which is the planted offset. Min-max above 1 is how EKENE-6''s hot shale is found, the null-target refusal is how the no-sonic well is found, and the pay rule reads PHIC and RT, which the offset does not touch.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 13, 'The Ekene wells are drawn with the canonical mulberry32 on the stated seed 20260913. What does that give a learner?', '["A different field on every run, so each learner practises on fresh rows while the course numbers change.", "Rows sampled at random from a real well database, the seed recording which wells.", "A field whose rows match the real Ekene logs, which the seed was chosen to reproduce as closely as possible.", "The same file anywhere: the same inputs give the same rows, so every printed figure can be reproduced."]'::jsonb, 3, 'One stated seed and the one canonical mulberry32 give the same rows on any machine, which is why every figure in the course can be checked by rerunning the call. The Ekene field is synthetic: its offsets and its withheld sonic exist only because they were drawn, and no real well database is sampled.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 14, 'If the one-well workflow standardises the features, where does the scaler belong?', '["In step two, fitted on the 240 training rows and applied unchanged to EKENE-8.", "Before step one, fitted on all 270 sonic rows so that EKENE-8 shares the scale.", "In step four, fitted on EKENE-8''s 30 rows just before the held-out well is scored.", "At the end, after scoring, since scaling changes nothing a least squares fit returns."]'::jsonb, 0, 'The scaler is fitted in the fitting step, on the same training rows as the model, and applied unchanged to the held-out well. Fitted before the split it has seen EKENE-8, and fitted on EKENE-8 it lets the well shape its own transform. For least squares the predictions are the same either way up to rounding, but the coefficients change units, so the scaler is part of the model and is fitted with it.'),
  ('mlcore', 'beginner', 'module', 'm06-one-well-held-out', 15, 'EKENE-6 has GR, RHOB and NPHI on every row but no sonic. What can the one-well workflow do with it in a real field?', '["Hold it out with nTestGroups 1 and score it like any other well, since its logs are all present.", "Predict its DT from its logs, though with no measured DT there is nothing to score the prediction against.", "Nothing at all, since `predict` refuses any row whose DT is null, even when the model has been fitted.", "Fit on it with the other eight wells, since the null DT values are filled from the training mean."]'::jsonb, 1, '`predict` needs only the fitted model and the rows'' features, so EKENE-6''s DT can be predicted. Scoring needs a measured target, and EKENE-6 has none: every DT sample is null, and `ols` refuses a null target by name, so the well can neither train nor be scored. The engine fills no missing value.'),
  ('mlcore', 'beginner', 'final', null, 1, 'When the engine refuses a call, how does the message it returns begin?', '["With a code number that indexes the engine''s list of refusals, followed by the refused value.", "With the word error and the name of the function that was called.", "With the name of the input it refused, the same name the result carries in its `field`.", "The row count of the call comes first, so the caller can see how much data reached the engine."]'::jsonb, 2, 'Every refusal is an object with `error` and `field`, where `field` names the input it refused and the message starts with that name: "y[20] must be a finite number" begins with the field `y[20]`. No code number is involved, and the message carries only the figures its own sentence needs.'),
  ('mlcore', 'beginner', 'final', null, 2, 'A manager asks for a band around each predicted DT showing how far off it might be. What does the engine supply?', '["No such band: it gives no prediction intervals, and its only random draws are seeded shuffles.", "A band of two residual standard errors either side of each prediction, returned by `predict`.", "Repeated random draws of the inputs, seeded so that the band repeats on every run.", "The band that the standard errors of the coefficients give, printed beside each predicted row."]'::jsonb, 0, 'The engine does not sample input distributions or give prediction intervals. The only random draws it makes are seeded shuffles. `predict` returns predicted values alone, and the standard errors describe the coefficients.'),
  ('mlcore', 'beginner', 'final', null, 3, 'A colleague expects the engine to try GR, RHOB, NPHI and CALI in every combination and return the best sonic model. What will it do?', '["Search every subset and return the one with the lowest test RMSE, with the others listed in its basis.", "Fit all four logs at once and drop, without comment, any whose coefficient comes out close to zero.", "Refuse the call, since the engine accepts at most three features in a least squares fit.", "Fit exactly the features it is handed; choosing among them is the caller''s work, with the scores printed."]'::jsonb, 3, 'The engine does not choose the features or the model. A course or an app does that and prints the scores it compared. It fits whatever design it is given, drops nothing silently, and sets no limit of three features.'),
  ('mlcore', 'beginner', 'final', null, 4, '`ols` is handed a target column in which every DT value is equal. What does it return?', '["A fit with every coefficient at zero and the intercept equal to that one value of DT, with R-squared 1.", "No fit: it refuses on `y`, since a target sum of squares of zero leaves R-squared undefined.", "Coefficients as usual, with R-squared reported as 0 since there is no variation to explain.", "It drops the target and fits the features against each other, reporting that change in its basis."]'::jsonb, 1, 'With every target equal, the total sum of squares about the mean is zero, so R-squared has no denominator. The engine refuses on the field `y` and returns no coefficients at all, since it will not print a fit whose score it cannot define. It never swaps the target for another column.'),
  ('mlcore', 'beginner', 'final', null, 5, 'A scaler has already been fitted on the training rows. Which function turns the test rows into scaled values with it?', '["`applyScaler`, which transforms any rows with the fitted parameters, unchanged.", "`fitStandardScaler` called again on the test rows, so that they are centred on themselves.", "`predict`, which scales each row before applying the rule.", "`regressionMetrics`, which standardises what it scores."]'::jsonb, 0, 'The function table gives `applyScaler` the scaler and X, and it returns rows transformed with the fitted parameters, unchanged. Fitting again on the test rows would let them shape their own transform. `predict` applies a fitted model to the rows it is handed, and `regressionMetrics` compares targets with predictions.'),
  ('mlcore', 'beginner', 'final', null, 6, 'A report says the gamma ray "was standardised by its standard deviation". Under this course''s rule for that phrase, what is missing?', '["The feature''s unit, since a standard deviation must always be quoted in the unit of the log it describes.", "The number of rows, since a standard deviation is only defined for more than thirty rows of a well.", "Its divisor: the population standard deviation divides by n, and the sample one by n - 1.", "Nothing, since every tool computes a standard deviation in the same way on the same rows."]'::jsonb, 2, 'The course''s rule: a standard deviation names its divisor. This engine''s scaler uses the population standard deviation, n, and the data quality course''s z-score uses the sample standard deviation, n - 1. On 180 rows the two differ by the factor 1.002789, which is why a report that omits the divisor cannot be checked.'),
  ('mlcore', 'beginner', 'final', null, 7, 'How are the 300 rows of the Ekene field organised?', '["30 wells of 10 samples each, at one shared set of depths.", "10 wells of 30 samples each, at a one foot step, each well at its own depth.", "One long well of 300 samples at a one foot step, which the course cuts into ten pieces of 30.", "20 wells of 15 samples each, at a half foot step through one interval."]'::jsonb, 1, 'The Ekene field has 10 wells, EKENE-1 to EKENE-10, each with 30 samples at a one foot step through the same reservoir interval, each well at its own depth: 300 rows. EKENE-6 is one of the ten, sampled like the others, and has no sonic, which is why 270 rows in 9 wells carry a DT.'),
  ('mlcore', 'beginner', 'final', null, 8, '`randomRowSplit` on the 270 sonic rows at test fraction 0.3 and seed 5 holds out 81 rows. How many rows train the model?', '["180, the same training set as the split by whole wells at this seed and fraction.", "270, since a random-row split trains on every row and scores the held-out rows a second time.", "90, since a random-row test set is always the rows of three wells at this test fraction.", "189, the rows left once the 81 test rows are taken from the 270."]'::jsonb, 3, 'The random-row split holds out ceil(0.3 x 270) = 81 rows and trains on the other 189. 180 is the training count of the whole-well split, which holds out 90 rows of three wells. No split trains on its own test rows.'),
  ('mlcore', 'beginner', 'final', null, 9, 'Fisher-Yates from the end opens at i = 8, and for seed 5 its first draw is 0.689775. Which j results, and which two names trade places?', '["5, since j = floor(u x 8) takes the draw over the eight positions below i.", "6, since j = floor(u x 9), and EKENE-9 swaps with EKENE-7.", "7, since u is rounded to the nearest position before the swap is made in the list of names.", "0, since the first draw of any shuffle always swaps the last name with the first."]'::jsonb, 1, 'Fisher-Yates from the end takes j = floor(u x (i + 1)), and at i = 8 that is floor(0.689775 x 9) = 6, so EKENE-9 swaps with EKENE-7, as the course''s table of draws records. The multiplier is i + 1, the draw is floored, and no rule fixes the first swap.'),
  ('mlcore', 'beginner', 'final', null, 10, 'Two analysts split the nine sonic wells by whole wells at the same fraction, 0.3, one with seed 3 and the other with seed 4. Which wells end up in both test sets?', '["EKENE-4 and EKENE-5, which appear in both draws.", "EKENE-2, EKENE-3, EKENE-4 and EKENE-5, the union of the wells that the two draws hold out.", "None of them, since two different seeds always hold out two disjoint sets of test wells.", "The same three wells, since seeds that differ by one give the same draw at a fraction of 0.3."]'::jsonb, 0, 'Seed 3 holds out EKENE-2, EKENE-4 and EKENE-5, and seed 4 holds out EKENE-3, EKENE-4 and EKENE-5, so EKENE-4 and EKENE-5 are common to both. A seed fixes a draw and nothing else, so two seeds can share some wells and differ in others; neighbouring seeds carry no special relation.'),
  ('mlcore', 'beginner', 'final', null, 11, 'A `groupSplit` call passes well names as a list that begins with the text "EKENE-1" and then has the number 2. What happens?', '["The number is turned into text, so the two names sort together as strings before the shuffle.", "The engine sorts the numbers first and the text names after them, then shuffles the whole list.", "A refusal on `groups[1]`: every group id must be of the same type, all strings or all numbers.", "Dropping the number as an unreadable name, and splitting the remaining text names as usual."]'::jsonb, 2, 'The engine''s own words are: "groups[1] must be the same type as groups[0]: all strings or all numbers". It converts nothing, sorts no mixed list and drops no entry: it refuses and names the first entry whose type differs.'),
  ('mlcore', 'beginner', 'final', null, 12, '`groupSplit` is handed rows that all come from EKENE-1. What does it return?', '["One test well and no training well, as 0.3 of one well rounds up to one.", "A random-row split of EKENE-1''s 30 rows, with a note in the basis that one well cannot be held out.", "All 30 rows as training rows and an empty test set, since one well cannot be split any further.", "A refusal on `groups`: at least 2 distinct groups are needed to hold one out, and it found 1."]'::jsonb, 3, 'The engine''s own words are: "groups must hold at least 2 distinct groups to hold one out (found 1)". A split by whole wells needs one well to train and one to test. The engine never switches to another kind of split, and it returns no empty side.'),
  ('mlcore', 'beginner', 'final', null, 13, 'If the wells are named by numbers alone, 1 to 10, in which order does the engine sort them before the shuffle?', '["Ascending, so 2 comes before 10; names that are all numbers sort as numbers.", "Character by character, so 10 comes before 2, exactly as it does for text names.", "In the order the rows arrive, since numbers need no sorting before a shuffle.", "Descending, so the shuffle starts from the highest number and works down."]'::jsonb, 0, 'Names that are all numbers sort ascending; only names that are strings sort by UTF-16 code unit, which is why the text EKENE-10 comes before EKENE-2. A list of numbers is sorted like any other list before the shuffle, and the order is stated in the basis.'),
  ('mlcore', 'beginner', 'final', null, 14, 'At seed 5 the shuffled order of the nine sonic wells begins EKENE-8, EKENE-4, EKENE-5, EKENE-2. Which call holds out EKENE-8 and EKENE-4 and nothing else?', '["`groupSplit` with testFraction 0.3 and seed 5, which holds out the first two names of that order.", "`groupSplit` with nTestGroups 2 and seed 5.", "`groupSplit` with nTestGroups 1 and seed 5, called twice so that each call adds one more well.", "`groupSplit` with nTestGroups 2 on the sorted list before the shuffle, which the seed then fixes."]'::jsonb, 1, 'The first nTest groups of the shuffled order are the test set, so nTestGroups 2 at seed 5 holds out EKENE-8 and EKENE-4. The fraction 0.3 holds out ceil(0.3 x 9) = 3 wells, adding EKENE-5. Repeating a call with the same seed gives the same one well, and the first two sorted names are EKENE-1 and EKENE-10.'),
  ('mlcore', 'beginner', 'final', null, 15, 'Fitted on the 180 training rows with the default divisor, which scale does the standard scaler give NPHI?', '["0.033238, the scale over all 270 sonic rows, since NPHI reads alike in every well of the field.", "0.033597, the sample standard deviation, since the scaler divides by n - 1 unless told otherwise.", "0.255072, the centre of the training rows, since a scale is taken about the mean of the log.", "0.033503, the population standard deviation of those 180 rows."]'::jsonb, 3, 'The scaler''s default divisor is n, the population standard deviation, fitted on the training rows: 0.033503 for NPHI. 0.033597 is the sample standard deviation of the same rows, 0.033238 the scale over all 270 rows including the test wells, and 0.255072 is the training centre.'),
  ('mlcore', 'beginner', 'final', null, 16, 'For the first test row of the teaching split, RHOB reads 2.348000 and the training scaler gives z = -0.303186. Which arithmetic produces that z?', '["(2.348000 - 2.397719) / 0.136737, the centre and scale taken over all 270 sonic rows together.", "(2.348000 - 2.391150) / 0.142719, the training centre over the training sample standard deviation.", "(2.348000 - 2.391150) / 0.142322, the training centre and the training population scale.", "(2.348000 - 2.107000) / (2.734000 - 2.107000), min-max on the training range."]'::jsonb, 2, 'The standard scaler maps x to (x - centre) / scale with both fitted on the training rows and the population divisor: RHOB''s training centre is 2.391150 and its training scale 0.142322. The all-rows figures, 2.397719 and 0.136737, include the test wells, 0.142719 divides by n - 1, and the minimum over the range is min-max scaling.'),
  ('mlcore', 'beginner', 'final', null, 17, 'Min-max scaling fitted on the nine sonic wells is applied to EKENE-6. Which of its three logs lands outside 0 to 1?', '["GR alone, on 4 of the 30 rows; RHOB and NPHI stay inside the range.", "All three, since EKENE-6 was not among the wells the scaler was fitted on.", "RHOB alone, whose EKENE-6 maximum of 0.925040 is its largest scaled value on the chart.", "None of them, since min-max clips every new row into the training range of 0 to 1."]'::jsonb, 0, 'EKENE-6''s scaled GR runs up to 1.219324 and sits above 1 on 4 rows, the hot shale. Its RHOB runs from 0.181818 to 0.925040 and its NPHI from 0.057143 to 0.600000, both inside. Being a new well does not by itself put a row outside the range, and min-max clips nothing.'),
  ('mlcore', 'beginner', 'final', null, 18, 'What does `fitMinMaxScaler` return for each feature?', '["The training mean and the population standard deviation, the pair the standard scaler also uses.", "The training minimum and the training range, from which each row maps to (x - minimum) / range.", "The minimum and maximum over every row it is later applied to, refitted each time it is used.", "A clipped copy of the rows, each value forced into 0 to 1 before the model sees it."]'::jsonb, 1, 'The function table gives `fitMinMaxScaler` the training minimum and range per feature: the minimum maps to 0 and the maximum to 1. Those two numbers are fitted once, on the training rows, and applied unchanged. The mean and the population standard deviation belong to the standard scaler, and min-max clips no row.'),
  ('mlcore', 'beginner', 'final', null, 19, 'The sample standard deviation divides by n - 1 and the population one by n. Why does this engine''s scaler use n by default?', '["Because n - 1 is refused whenever a feature is constant down any one of the training wells.", "The sample divisor gives a smaller scale, which would push the z values towards zero.", "Because the data quality course uses n, and the two courses share one scaler across the academy.", "A stated choice: it reproduces the figure scikit-learn''s StandardScaler gives, which divides by n."]'::jsonb, 3, 'The basis says the scaler uses the "population standard deviation (n), as scikit-learn StandardScaler", and the course names this as a choice: another tool dividing by n - 1 returns a different scale from the same rows. The data quality course uses the sample standard deviation for its z-score. Dividing by n - 1 gives the larger scale, and no divisor is refused because a well is constant.'),
  ('mlcore', 'beginner', 'final', null, 20, 'A feature reads the same on every training row except one. Is it refused as constant?', '["Yes, since a feature that varies on a single row carries too little spread to be scaled.", "Yes, unless the engine first drops the one row that differs.", "No: a feature is refused as constant only when every training value is identical.", "No, but its scale is set to 1 by the engine so that the other rows keep their raw values."]'::jsonb, 2, 'The engine refuses a feature as constant only when every training value is identical, and names it, as with EKENE-1''s mud weight. One differing row gives a non-zero scale, and the scaler fits it. The engine drops no row and sets no scale by hand.'),
  ('mlcore', 'beginner', 'final', null, 21, '`fitStandardScaler` is given all 270 sonic rows together with `trainIndices` listing the 180 training rows of the teaching split. What centre does it fit for GR?', '["60.250741, the mean of all 270 rows passed, since the scaler reads every row it is given.", "59.844500, the mean of the 180 rows `trainIndices` lists.", "22.375203, since with `trainIndices` given the scaler returns the scale in place of the centre.", "A refusal, since the scaler must be passed the training rows alone and cannot take a list of them."]'::jsonb, 1, 'The scaler fits on the rows passed or on the rows `trainIndices` lists, so with the list it fits on the 180 training rows: GR''s centre is 59.844500 gAPI. 60.250741 is the all-rows centre, which includes the three test wells, and 22.375203 is the training scale.'),
  ('mlcore', 'beginner', 'final', null, 22, 'The teaching fit reports a TSS of 18853.190000. What is it?', '["The sum of squared differences of the 180 training DT values from their own mean.", "The sum of squared residuals the plane leaves on the training rows, which least squares minimised.", "The sum of squared misses on the 90 test rows about the mean of the test targets.", "The total of all the training DT values, from which the training mean is divided out."]'::jsonb, 0, 'TSS is taken about the training mean: the total variation of DT on the 180 rows before any feature is used. The residual sum, RSS, is 5967.842781, and R-squared is 1 - RSS / TSS, 0.683457. Test rows play no part in the training fit.'),
  ('mlcore', 'beginner', 'final', null, 23, 'Which arithmetic gives the teaching fit''s residual standard error, 5.823075 us/ft?', '["sqrt(5967.842781 / 180), the root of the RSS over every training row.", "sqrt(5967.842781 / 179), the root of the RSS over n - 1 like a sample standard deviation.", "sqrt(18853.190000 / 176), the root of the TSS over the residual degrees of freedom.", "sqrt(5967.842781 / 176), the root of the RSS over n - p, with p counting the intercept."]'::jsonb, 3, 's^2 = RSS / (n - p), with n 180 and p 4 counting the intercept, so s is sqrt(5967.842781 / 176) = 5.823075 us/ft. Dividing the RSS by 180 gives the training RMSE, 5.758010. n - 1 ignores the three features, and the TSS measures the spread before the fit.'),
  ('mlcore', 'beginner', 'final', null, 24, 'Fitted on NPHI alone, the training R-squared is 0.001327; in the three-log fit NPHI''s t value is 6.319645. Do the two contradict each other?', '["Yes, and the three-log fit should be discarded, since a log with no signal alone cannot gain one.", "Yes, since a t value above 2 needs the feature to explain most of the variation on its own.", "No: what a coefficient says depends on which other features are in the fit beside it.", "No, since the t value comes from the test wells."]'::jsonb, 2, 'A coefficient depends on which other features are in the model. Alone, NPHI''s coefficient is 11.127468 and explains almost none of the variation; beside GR and RHOB, holding them fixed, its coefficient is 138.783590 with a t value of 6.319645. Both figures are training figures, and neither fit is wrong.'),
  ('mlcore', 'beginner', 'final', null, 25, '`ols` is given GR and DT as features on the forty rows from 130 to 169, with RHOB as the target. Which field does the refusal name?', '["`X[20][1]`: DT, the second column, is null at index 20 of the rows handed over, dataset row 150.", "`y[20]`, since the refusal always names the target whenever a row of the call is incomplete.", "`X[150][1]`, since the engine counts rows by their place in the full 300-row dataset.", "`X.DT`, since the engine names the column with the missing values and leaves out the row."]'::jsonb, 0, 'The engine''s own words are: "X[20][1] must be a finite number: fill or drop missing values first". Indices start at 0 within the call, so index 20 is dataset row 150, where EKENE-6 begins and its DT, the feature in column 1, is null. RHOB is the target in this call and is present throughout.'),
  ('mlcore', 'beginner', 'final', null, 26, 'A least squares fit with an intercept and three features is attempted on very few rows. What is the fewest rows the engine will accept?', '["4, one row for each coefficient, the intercept included.", "3, one row for each feature, since the intercept is not counted among the coefficients.", "30, one full well, since the engine fits no coefficient on fewer rows than a well carries.", "5, so that n - p is at least 1 with p = 4 counting the intercept."]'::jsonb, 3, 'The engine refuses n <= p and needs the residual degrees of freedom n - p to be at least 1. With the intercept p is 4, so 5 rows is the fewest it accepts. With 4 rows the plane passes through every row and leaves nothing to estimate s from. No one-well minimum exists.'),
  ('mlcore', 'beginner', 'final', null, 27, 'The teaching fit gives RHOB a coefficient of 22.499915. In what unit?', '["g/cm3 per us/ft, since the coefficient converts a sonic reading back into a density.", "us/ft per g/cm3, the target''s unit over the feature''s unit.", "us/ft alone, the unit of DT, since a coefficient takes the target''s unit and nothing else.", "None at all: a coefficient is a pure number fitted to the rows of the training wells."]'::jsonb, 1, 'A coefficient carries the target''s unit over the feature''s unit: one more g/cm3 of bulk density moves the fitted DT by 22.499915 us/ft, holding GR and NPHI fixed. The fit predicts DT from RHOB and never the other way, and a coefficient without its unit is a number without a meaning.'),
  ('mlcore', 'beginner', 'final', null, 28, 'What would dropping the intercept from the teaching fit force on the fitted plane?', '["Nothing: the coefficients would absorb it.", "A smaller residual standard error, since one fewer coefficient frees a residual degree of freedom.", "It would have to pass through the origin, where every log reads zero.", "An R-squared about zero, which the engine refuses."]'::jsonb, 2, 'The intercept is there so the plane need not pass through the origin, the fitted DT where every feature is zero, a point far outside the data. Without it the plane is pinned there and the coefficients bend to reach the rows. The fit would change, and a coefficient fewer does not by itself make the misses smaller.'),
  ('mlcore', 'beginner', 'final', null, 29, 'On the same rows, which relation between RMSE and MAE always holds?', '["MAE is at least as large as RMSE, since it keeps every miss at its full size and takes no root of a square.", "The two are equal whenever the model is fitted by least squares on those rows, since that fit balances the misses.", "RMSE is MAE squared, since both are built from the same misses on the same rows and one of them is squared.", "Up to rounding, RMSE is at least as large as MAE, and the two meet only when every miss has one size."]'::jsonb, 3, 'Squaring before averaging gives large misses more weight, so in exact arithmetic the root of the mean square is never below the mean of the sizes, and the two meet only when every miss has the same size. The engine works in floating point, so where every miss has one size the two can differ in the last digit, either way; the relation holds up to that rounding. On real rows the gap is plain: the test wells read RMSE 4.282693 and MAE 3.526103 us/ft. Least squares minimises squared misses, which makes the two no more alike, and both read in us/ft.'),
  ('mlcore', 'beginner', 'final', null, 30, 'On the three test wells the same predictions give R-squared 0.815322 about the test mean and 0.816151 about the training mean. Why is the second one higher?', '["The training mean is the better reference for a new well, and a better reference always scores higher.", "Rounding: the two agree to three decimals, and the gap is only the order in which the sums are taken.", "The training mean includes more rows, so it predicts the test targets more closely than their own mean.", "The squared spread of the test targets is smallest about their own mean, so any other reference enlarges it."]'::jsonb, 3, 'R-squared = 1 - SSE / sum (y - reference)^2, with the same SSE both times. The sum of squared differences of the test targets is as small as it can be about their own mean, 105.214444, so about 105.883333 the denominator is larger and R-squared comes out higher. Neither reference is better in general; each answers its own question and must be named.'),
  ('mlcore', 'beginner', 'final', null, 31, 'Scored on its own 180 fitted values, `regressionMetrics` returns R-squared 0.683457. Which reference mean is that about?', '["105.214444 us/ft, the mean of the test targets, which is the default for every R-squared the engine returns.", "105.883333 us/ft, the training mean, because the rows scored are the training rows.", "Zero, since fitted values are scored against the origin of the fitted plane.", "The mean of the fitted values, which differs from the mean of the measured DT."]'::jsonb, 1, 'With no `referenceMean`, R-squared is taken about the mean of the rows scored. Scored on the training rows, that is the training mean, 105.883333 us/ft, and the result matches the fit''s own R-squared, 0.683457. 105.214444 is the mean of the test targets, a different set of rows.'),
  ('mlcore', 'beginner', 'final', null, 32, 'In the 270-row fit, EKENE-9''s residuals average 6.733268 us/ft. Is the plane predicting that well''s DT too high or too low?', '["Too high, since a positive residual means the prediction overshoots the measured DT.", "Neither, since the residuals of a fit with an intercept average zero in every well.", "Too low: a residual is y - yhat, so a positive mean says the measured DT sits above the plane.", "It depends on the scale, since a residual has no sign until the features are standardised."]'::jsonb, 2, 'A residual is y - yhat for one row, measured less predicted. A positive mean residual says EKENE-9''s measured DT sits above the plane on average. With an intercept the residuals sum to zero over all fitted rows together, never well by well, and a residual keeps its sign in us/ft whatever the features'' scale.'),
  ('mlcore', 'beginner', 'final', null, 33, 'The teaching fit''s training R-squared is 0.683457; least squares on all 270 sonic rows reads 0.728027. Why do they differ?', '["They are fits to different rows: 180 training rows of six wells, and all 270 rows of nine wells.", "The 270-row value is a test R-squared, taken about the training mean of the teaching split.", "The 270-row fit uses standardised features, which raises R-squared on the same rows.", "One is adjusted for the coefficients spent and the other is not, on the same set of rows."]'::jsonb, 0, 'Each R-squared belongs to its fit and its rows: 0.683457 is the teaching fit on its 180 training rows, and 0.728027 the fit on all 270 sonic rows, each about its own training mean. Neither is a test figure, standardising leaves a least squares fit unchanged, and the teaching fit''s adjusted value is 0.678062.'),
  ('mlcore', 'beginner', 'final', null, 34, 'EKENE-8 scores RMSE 3.501687 us/ft as a test well of the teaching split and 3.765285 when it is the one well held out. Why do the two differ?', '["The second figure also counts EKENE-8''s training rows.", "The first is taken about EKENE-8''s own mean and the second about the training mean of the fit.", "Rounding in the pooling of the 90 test rows shifts the first figure away from the second.", "They come from different planes: one fitted on six training wells, the other on eight."]'::jsonb, 3, 'The teaching split trains on six wells, 180 rows, and the one-well workflow on eight, 240 rows, so the planes differ and so do their misses on EKENE-8''s 30 rows. Both figures are test scores on EKENE-8 alone, and RMSE needs no reference mean.'),
  ('mlcore', 'beginner', 'final', null, 35, 'How many residuals does the least squares fit on all 270 sonic rows return, and what is each one?', '["9, one per well, each the mean miss of that well''s 30 rows.", "Fewer than 270, since the 4 coefficients use up four rows that carry no residual.", "270, one per fitted row, each the measured DT less the fitted DT of that row.", "30, one per depth step, averaged across the nine wells at that depth."]'::jsonb, 2, 'A residual is y - yhat for one row, so a fit on 270 rows returns 270 of them. The well means, such as EKENE-9''s 6.733268 us/ft, are derived by averaging each well''s 30 residuals. The coefficients take degrees of freedom from the fit without taking any row''s residual away.'),
  ('mlcore', 'beginner', 'final', null, 36, 'Of the five wells held out one at a time, which does the plane miss by the most?', '["EKENE-3 at seed 4, whose RMSE of 3.564857 us/ft is the largest of the five.", "EKENE-7 at seed 6, with an RMSE of 6.502833 us/ft and the lowest R-squared of the five.", "EKENE-2 at seed 3, with an RMSE of 7.260092 us/ft and an R-squared of 0.482707.", "EKENE-8 at seed 1, since the first well held out is scored against the fewest training rows."]'::jsonb, 2, 'Held out one at a time, EKENE-2 reads RMSE 7.260092 us/ft, the largest of the five, with R-squared 0.482707 about its own mean. EKENE-3''s 3.564857 is the smallest of the five. EKENE-7 reads 6.502833 with R-squared 0.502611, above EKENE-2''s 0.482707, and every one-well fit trains on the same count of eight wells.'),
  ('mlcore', 'beginner', 'final', null, 37, 'Step five of the one-well workflow scores the training rows for comparison. What does it return?', '["RMSE 5.462405 us/ft and R-squared 0.709438 on the fitted values of the 240 training rows.", "RMSE 3.765285 us/ft on EKENE-8, which is scored a second time against the training mean.", "RMSE 5.758010 us/ft on the 180 training rows of the teaching split, the course''s reference fit.", "The coefficients again, since a training score is the fit itself read back in us/ft."]'::jsonb, 0, 'Step five runs `regressionMetrics` on the fitted values of the 240 training rows: RMSE 5.462405 us/ft and R-squared 0.709438. 3.765285 is EKENE-8''s test RMSE from step four, and 5.758010 belongs to the teaching fit on 180 rows, a different split.'),
  ('mlcore', 'beginner', 'final', null, 38, 'With EKENE-8 held out, GR''s coefficient reads 0.320501 on the raw logs and 6.898926 on standardised logs. How can both describe one fitted plane?', '["They cannot, so the standardised fit must be a different plane that predicts EKENE-8 differently.", "The standardised fit drops the intercept, so its coefficients must grow to make up the difference.", "The larger figure is per 0.01 gAPI, the rate the course uses for a gamma ray reading.", "Each reads in its own unit: one per gAPI, the other per population SD of GR across the eight training wells."]'::jsonb, 3, 'Standardising changes the unit of a coefficient to us/ft per population standard deviation of its feature over the training rows. The predictions for EKENE-8 differ from the raw fit''s by at most 1.42e-14 us/ft, which is rounding: least squares with an intercept gives the same plane under any rescaling of a feature. Both fits keep an intercept.'),
  ('mlcore', 'beginner', 'final', null, 39, 'Which of the planted items in the Ekene field does min-max scaling fitted on the nine sonic wells find?', '["The well-level sonic offset, which min-max maps above 1 in every well that carries one.", "The hot shale in EKENE-6, whose raised gamma ray maps above 1 on 4 rows.", "EKENE-6''s missing sonic, refused at its first null row.", "The pay label, recovered by mapping PHIC above 0.16 to 1."]'::jsonb, 1, 'EKENE-6''s gamma ray is raised by 30 gAPI on every sample, and min-max fitted on the nine sonic wells maps its highest GR above 1 on 4 rows. The sonic offset is found by the mean least squares residual per well, and the missing sonic by the refusal of the first null target. PAY is a label from a stated rule, which scaling does not find.'),
  ('mlcore', 'beginner', 'final', null, 40, 'In a write-up of the teaching fit, how does the course name the method?', '["As machine learning, since the course is about machine learning on well data and that names the family.", "By its test score on the held-out wells.", "As ordinary least squares with an intercept, the method named by what it is.", "As a sonic predictor, named for its target."]'::jsonb, 2, 'The course''s rule: machine learning here means a fitted statistical model named by its method, so a write-up names it as ordinary least squares with an intercept. A score describes how the model did on some rows, and the target is a separate line of the write-up.'),
  ('mlcore', 'beginner', 'final', null, 41, 'A colleague reruns the one-well workflow with the same wells, the same seed and the same features. What will they get?', '["The same five results, since each step is an engine call with stated inputs.", "Slightly different results, as the split draws afresh.", "The same test well but different coefficients, since least squares starts from random values.", "Matching results only on the same machine."]'::jsonb, 0, 'Each row of the workflow table is an engine call with stated inputs: the split''s only draws come from one mulberry32 stream seeded by the stated seed, and least squares has no random start. Anyone with the same wells, seed and features gets the same five results, which is what lets a score be checked and argued with.'),
  ('mlcore', 'beginner', 'final', null, 42, 'Why can a plane fitted on the other eight wells not know EKENE-8''s own sonic offset?', '["Because the offset is removed from EKENE-8''s rows before the fit, as the split''s basis states.", "Because the offset is carried by GR alone, which the fit reads only through its training centre.", "It can, since the intercept is fitted to the mean offset of all nine wells, EKENE-8 included.", "The offset belongs to EKENE-8 alone, and none of EKENE-8''s rows is in the fit."]'::jsonb, 3, 'Each Ekene well carries its own planted sonic offset, shared by all its rows. A whole-well split keeps every EKENE-8 row out of the fit, so nothing in the fitted rows carries that well''s offset and the plane has no way to learn it. Nothing is removed from any row, and the offset is added to DT itself.');
